# Parses (does not run) a .ps1 file and exits nonzero with the errors on stdout if it
# doesn't parse. Used by tests/test_make_relay_package.py to catch quoting/templating
# mistakes in the PowerShell generated by tools/make_relay_package.py without actually
# installing anything.
param([Parameter(Mandatory = $true)][string]$Target)

$tokens = $null
$errors = $null
[void][System.Management.Automation.Language.Parser]::ParseFile($Target, [ref]$tokens, [ref]$errors)
if ($errors.Count -gt 0) {
    $errors | ForEach-Object { Write-Output $_.ToString() }
    exit 1
}
exit 0
